// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract Caller {
    function callTransfer(airDrop _c, address from, address caddress, address[] memory _tos, uint v, uint _decimals) external returns (bool) {
        try _c.transfer(from, caddress, _tos, v, _decimals) returns (bool ret) {
            return ret;
        } catch {
            return false;
        }
    }
}

contract InvMutTest is Test {
    airDrop c;
    Caller caller;

    function setUp() public {
        c = new airDrop();
        caller = new Caller();
    }

    function testFuzz_property(
        address from,
        address caddress,
        address[] memory _tos,
        uint256 v,
        uint256 _decimals
    ) public {
        vm.assume(_tos.length > 0);
        _decimals = bound(_decimals, 0, 18);
        v = bound(v, 0, type(uint256).max / (10 ** _decimals));

        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v, _decimals)
        );
        vm.assume(success);

        bool ret = caller.callTransfer(c, from, caddress, _tos, v, _decimals);
        assertTrue(ret);
    }
}
